    if rest[0] == "run":
        return len(rest) > 1 and rest[1] in SHELL_SAFE_RUN_SCRIPTS
    return rest[0] in SHELL_SAFE_SUBCOMMANDS.get(head, set())


def _safe_make(rest: list[str]) -> bool:
    """make 타깃이 빌드/검증 계열인지 판단한다(clean·install·deploy는 제외)."""
